describe('Login Loading Spinner', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display loading spinner while login request is processing', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 200,
      body: { token: 'abc123', userId: 1 }
    }).as('loginRequest');

    // Verify spinner is visible
    cy.get('[data-testid="spinner"]').should('be.visible');
    cy.get('[data-testid="spinner"]').should('contain', 'Loading...');

    // Fill login form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for API call
    cy.wait('@loginRequest');

    // Verify spinner is hidden
    cy.get('[data-testid="spinner"]').should('not.exist');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Login successful');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');
  });

  it('should not display spinner when login fails', () => {
    // Intercept failed login API call
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('loginRequest');

    // Fill login form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for API call
    cy.wait('@loginRequest');

    // Verify spinner is still visible
    cy.get('[data-testid="spinner"]').should('be.visible');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Verify user is not redirected
    cy.url().should('include', '/login');
  });
});
